package com.trombokendu.chronos.concurrency;import com.trombokendu.chronos.domain.*;import com.trombokendu.chronos.ledger.*;import com.trombokendu.chronos.persistence.*;import java.sql.Connection;import java.util.concurrent.*;public final class LedgerWriter implements AutoCloseable{private final BlockingQueue<WriteCommand> q=new LinkedBlockingQueue<>();private final EventStore store;private final EventBus bus;private final ConnectionPool pool;private final EventRepository repository;private final Thread thread;private volatile boolean stopping;public LedgerWriter(EventStore s,EventBus b){this(s,b,null,null);}public LedgerWriter(EventStore s,EventBus b,ConnectionPool p,EventRepository r){store=s;bus=b;pool=p;repository=r;thread=new Thread(this::loop,"ledger-writer");thread.start();}public CompletableFuture<StoredEvent> submit(LedgerEvent e){CompletableFuture<StoredEvent> f=new CompletableFuture<>();if(stopping){f.completeExceptionally(new IllegalStateException("writer stopping"));return f;}q.add(new WriteCommand(e,f));return f;}private void loop(){while(!stopping||!q.isEmpty()){try{WriteCommand c=q.poll(200,TimeUnit.MILLISECONDS);if(c!=null)try{StoredEvent s;if(pool!=null&&repository!=null){String prev=store.all().isEmpty()?HashChain.GENESIS:store.all().getLast().hash();s=new StoredEvent(store.all().size()+1L,c.event(),prev,HashChain.next(prev,c.event()));try(Connection connection=pool.get();UnitOfWork uow=new UnitOfWork(connection)){repository.insert(connection,s);uow.commit();}store.append(c.event());}else{s=store.append(c.event());}bus.publish(c.event());c.result().complete(s);}catch(Throwable t){c.result().completeExceptionally(t);}}catch(InterruptedException e){if(stopping)break;Thread.currentThread().interrupt();}}}public void close(){stopping=true;try{thread.join(5000);}catch(InterruptedException e){Thread.currentThread().interrupt();}}}
